// Inherit real native blast/damage tests, then add density-driven volley checks.
#define Generate_Mission_Starts Blast_Regression
#include "../tests/samblast_engine.cpp"
#undef Generate_Mission_Starts
#include "campaignenemies.h"
static int Volley(BuildingClass* sam,TechnoClass* target){int before=Bullets.Count();auto missile=static_cast<TechnoClass*>(sam)->Fire_At(target->As_Target(),0);Check("normal firing creates a base missile",missile!=nullptr);int count=Bullets.Count()-before;for(int i=Bullets.Count()-1;i>=0;--i){Check("all salvo missiles have twice-stock power",Bullets.Ptr(i)->Strength==100);delete Bullets.Ptr(i);}return count;}
static void Density(const std::string& dir,int enemies){Reset(dir);auto sam=new BuildingClass(STRUCT_SAM,HOUSE_GOOD);Check("place density SAM",Put(sam,Center()));sam->PrimaryFacing=DIR_N;
 std::vector<UnitClass*> group;for(int i=0;i<enemies;++i){auto enemy=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place nearby hostile",Put(enemy,XY_Cell(Cell_X(Coord_Cell(sam->Coord))+2,Cell_Y(Coord_Cell(sam->Coord))+2)));Check("enemy fixture inside ten-cell circle",Distance(sam->Center_Coord(),enemy->Center_Coord())<=10*ICON_LEPTON_W);enemy->Strength=30000;group.push_back(enemy);}
 auto distant=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place distant target",Put(distant,XY_Cell(Cell_X(Coord_Cell(sam->Coord))+14,Cell_Y(Coord_Cell(sam->Coord)))));Check("distant enemy outside count",Distance(sam->Center_Coord(),distant->Center_Coord())>10*ICON_LEPTON_W);distant->Strength=30000;
 // Own, allied, neutral, dead and limbo actors must not inflate the count.
 for(auto house:{HOUSE_GOOD,HOUSE_JP,HOUSE_NEUTRAL}){if(house==HOUSE_JP){sam->House->Make_Ally(house);HouseClass::As_Pointer(house)->Make_Ally(HOUSE_GOOD);}auto f=new InfantryClass(INFANTRY_E1,house);Check("place excluded actor",Put(f,Coord_Cell(sam->Coord)));}
 auto dead=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place dead enemy fixture",Put(dead,Coord_Cell(sam->Coord)));dead->Strength=0;auto limbo=new UnitClass(UNIT_MTANK,HOUSE_BAD);(void)limbo;
 auto building=new BuildingClass(STRUCT_POWER,HOUSE_BAD);Check("place enemy building excluded from troop count",Put(building,Coord_Cell(sam->Coord)));
 int total=0;for(int i=0;i<5;++i){int before=int(sam->IsSecondShot);int n=Volley(sam,group.empty()?static_cast<TechnoClass*>(distant):group[0]);total+=n;Check("extra missiles preserve ordinary salvo phase",sam->IsSecondShot==(before==0));Check("extra missiles preserve normal rearm deadline",sam->Arm==sam->Rearm_Delay(before));}
 std::printf("DENSITY enemies=%d five_base_shots=%d expected=%d\n",enemies,total,5+enemies);Check("five normal shots add exactly enemy-count missiles",total==5+enemies);
 if(enemies==1){Campaign_SAM_Volley_Forget(sam);Check("fraction starts with one normal missile",Volley(sam,group[0])==1);int samId=Buildings.ID(sam),enemyId=Units.ID(group[0]);for(int i=0;i<Units.Count();++i)Campaign_Enemies_Mark_Extra(Units.Ptr(i));for(int i=0;i<Infantry.Count();++i)Campaign_Enemies_Mark_Extra(Infantry.Ptr(i));Check("save fractional volley credit",Save_Game((dir+"/fraction.sav").c_str(),"SAM FRACTION ONE FIFTH"));Check("reload fractional volley credit",Load_Game((dir+"/fraction.sav").c_str()));sam=Buildings.Ptr(samId);auto target=Units.Ptr(enemyId);int next=0;for(int i=0;i<4;++i)next+=Volley(sam,target);Check("saved fractional credit adds next missile at fifth normal shot",next==5);
 Campaign_SAM_Volley_Forget(sam);Volley(sam,target);delete sam;auto replacement=new BuildingClass(STRUCT_SAM,HOUSE_GOOD);Check("place replacement SAM",Put(replacement,Center()));int fresh=0;for(int i=0;i<4;++i)fresh+=Volley(replacement,target);std::printf("RECYCLED count=%d\n",fresh);Check("recycled building slot starts without stale credit",fresh==4);}
}
static void ScopeVolley(const std::string& dir){Reset(dir);auto sam=new BuildingClass(STRUCT_SAM,HOUSE_BAD);Check("place enemy SAM",Put(sam,Center()));auto target=new UnitClass(UNIT_MTANK,HOUSE_GOOD);Check("place enemy-SAM target",Put(target,Coord_Cell(sam->Coord)));int before=Bullets.Count();static_cast<TechnoClass*>(sam)->Fire_At(target->As_Target(),0);Check("enemy SAM keeps single stock missile",Bullets.Count()==before+1&&Bullets.Ptr(before)->Strength==50);}
static void MixedBoundary(const std::string& dir){Reset(dir);auto sam=new BuildingClass(STRUCT_SAM,HOUSE_GOOD);Check("place mixed-density SAM",Put(sam,Center()));std::vector<FootClass*> enemies;
 for(int i=0;i<2;++i){auto tank=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place mixed hostile tank",Put(tank,Coord_Cell(sam->Coord)));enemies.push_back(tank);auto inf=new InfantryClass(INFANTRY_E1,HOUSE_BAD);Check("place mixed hostile infantry",Put(inf,Coord_Cell(sam->Coord)));enemies.push_back(inf);}
 auto air=new AircraftClass(AIRCRAFT_ORCA,HOUSE_BAD);air->Altitude=AircraftClass::FLIGHT_LEVEL;Check("place mixed hostile aircraft",Put(air,Coord_Cell(sam->Coord)));enemies.push_back(air);
 Check("vehicles infantry and aircraft all contribute to volley",Volley(sam,enemies[0])==2);
 auto actor=enemies.back();auto origin=actor->Coord;auto center=sam->Center_Coord();actor->Coord=XY_Coord(Coord_X(center)+10*ICON_LEPTON_W,Coord_Y(center));Campaign_SAM_Volley_Forget(sam);Check("enemy at exactly ten cells is counted",Volley(sam,enemies[0])==2);
 actor->Coord=XY_Coord(Coord_X(center)+10*ICON_LEPTON_W+1,Coord_Y(center));std::printf("BOUNDARY requested=%d actual=%d\n",10*ICON_LEPTON_W+1,Distance(center,actor->Center_Coord()));Campaign_SAM_Volley_Forget(sam);Check("enemy beyond ten-cell radius is excluded",Volley(sam,enemies[0])==1);actor->Coord=origin;
 GameToPlay=GAME_SKIRMISH;int before=Bullets.Count();static_cast<TechnoClass*>(sam)->Fire_At(enemies[0]->As_Target(),0);Check("skirmish retains one stock missile",Bullets.Count()==before+1&&Bullets.Ptr(before)->Strength==50);GameToPlay=GAME_NORMAL;
}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);Blast_Regression(directory);for(int count:{0,1,4,5,10,20})Density(dir,count);MixedBoundary(dir);ScopeVolley(dir);std::printf("TOTAL DENSITY FAILURES %d\n",failures);return failures==0;}
